#!/usr/bin/env python3
"""Regenerates .github/scripts/sf_symbols.txt, the SF Symbols names the validators accept.

macOS only: the names and the OS release that introduced each of them are read
from the system symbol catalog. Run from the repository root:

    python3 .github/scripts/generate_sf_symbols.py            # MIN_IOS below
    python3 .github/scripts/generate_sf_symbols.py --min-ios 27.0

Only the symbols available on the oldest iOS the app supports are kept: an icon
that exists on the latest OS only would fall back to the default icon for part
of the users, so the validators treat it like an unknown name.

Run it again when the deployment target of the app (WebSSH_Native) moves, and
commit the new list. A newer macOS alone changes nothing in the output.
"""
import argparse, os, plistlib, sys

# Deployment target of the app (IPHONEOS_DEPLOYMENT_TARGET in WebSSH_Native).
MIN_IOS = "26.0"
CATALOG = "/System/Library/CoreServices/CoreGlyphs.bundle/Contents/Resources/name_availability.plist"
OUTPUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sf_symbols.txt")


def version(text):
    return tuple(int(part) for part in text.split("."))


parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
parser.add_argument("--min-ios", default=MIN_IOS, help=f"oldest iOS supported by the app (default {MIN_IOS})")
parser.add_argument("--catalog", default=CATALOG, help="path of name_availability.plist")
args = parser.parse_args()

try:
    with open(args.catalog, "rb") as handle:
        catalog = plistlib.load(handle)
except OSError as exc:
    sys.exit(f"Cannot read the symbol catalog ({exc}). This script runs on macOS only.")

minimum = version(args.min_ios)
# "2020" -> (14, 0): the iOS release that shipped each yearly symbol set.
releases = {year: version(oses["iOS"]) for year, oses in catalog["year_to_release"].items()}
symbols = catalog["symbols"]
unknown_years = sorted({year for year in symbols.values() if year not in releases})
if unknown_years:
    sys.exit(f"Symbol sets without an iOS release in the catalog: {unknown_years}")

names = sorted(name for name, year in symbols.items() if releases[year] <= minimum)
if not names:
    sys.exit(f"No symbol is available on iOS {args.min_ios}: check --min-ios")

with open(OUTPUT, "w", encoding="utf-8") as handle:
    handle.write("# SF Symbols names accepted by the validators (statebar/, snippets/).\n")
    handle.write("# Generated by .github/scripts/generate_sf_symbols.py: do not edit by hand.\n")
    handle.write(f"# Symbols available on iOS {args.min_ios}, the oldest release the app supports.\n")
    handle.write("\n".join(names) + "\n")

print(f"{len(names)} symbols available on iOS {args.min_ios} ({len(symbols) - len(names)} newer ones left out) -> {OUTPUT}")
